using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "BattleActionToThatTargetOmenLogic", menuName = "Data/Battle/Omens System/Omen Logic/BattleActionToThatTarget Omen Logic")]
public class BattleActionToThatTargetOmenLogic : OmenLogic
{
	[SerializeField]
	private DirectPurifyCorruptEnum directPurifyCorruptEnum;

	public override string GetLocalizedOmenLogicDescription(BattleAction battleAction, int actionValue)
	{
		string text = "";
		if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectPurify)
		{
			string arg = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedPurifyReceive(), actionValue);
			return Smart.Format(base.GetLocalizedOmenLogicDescription(battleAction, actionValue), arg);
		}
		if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectCorrupt)
		{
			string arg2 = Smart.Format(ReferenceSingleton<LocalizationManager>.Instance.GetLocalizedCorruptReceive(), actionValue);
			return Smart.Format(base.GetLocalizedOmenLogicDescription(battleAction, actionValue), arg2);
		}
		string actionNameForDescription = battleAction.GetActionNameForDescription();
		return Smart.Format(base.GetLocalizedOmenLogicDescription(battleAction, actionValue), actionValue, actionNameForDescription).LowercaseFirst();
	}

	public override void ActivateOmen(BattleAction battleAction, int actionValue, GameObject target, GameObject source, CorruptionPurifyModifierEnum corruptionPurifyModifierEnum = CorruptionPurifyModifierEnum.NONE, bool playSFX = false)
	{
		if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectPurify)
		{
			target.GetComponent<CorruptionStats>().Purify(actionValue, source);
		}
		else if (directPurifyCorruptEnum == DirectPurifyCorruptEnum.DirectCorrupt)
		{
			target.GetComponent<CorruptionStats>().Corrupt(actionValue, source);
		}
		else
		{
			battleAction.CastTargetAmount(target, actionValue, source);
		}
	}
}
